function livePresence(){return presenceSessions.filter(p=>p&&!p.isAdmin&&p.online)}
function recentPresence(){return presenceSessions.filter(p=>p&&!p.isAdmin).sort((a,b)=>(new Date(b.lastSeenAt||0).getTime()||0)-(new Date(a.lastSeenAt||0).getTime()||0)).slice(0,10)}

function formatDuration(ms){ms=Math.max(0,Number(ms||0));const sec=Math.floor(ms/1000);if(sec<60)return`${sec}s`;const min=Math.floor(sec/60),s=sec%60;if(min<60)return`${min}m ${s}s`;const h=Math.floor(min/60),m=min%60;return`${h}h ${m}m`}
function ghostSessions(){return presenceSessions.filter(p=>p&&!p.isAdmin&&p.ghost===true).sort((a,b)=>(new Date(b.lastSeenAt||0).getTime()||0)-(new Date(a.lastSeenAt||0).getTime()||0))}
function ghostLabel(p){const id=String(p.visitorId||p.sessionId||p.id||'').replace(/^v_|^s_|^session_/, '');return`Fantasma #${(id.slice(-6)||'ANON').toUpperCase()}`}
