function renderGhosts(){const body=$('ghostsBody');if(!body)return;const all=ghostSessions();const online=all.filter(p=>p.online);const avg=all.length?all.reduce((sum,p)=>sum+Number(p.durationMs||0),0)/all.length:0;const views=all.reduce((sum,p)=>sum+Number(p.pageViews||p.journey?.length||0),0);$('gOnline').textContent=online.length;$('gSessions').textContent=all.length;$('gAvg').textContent=formatDuration(avg);$('gViews').textContent=views;const q=($('ghostSearch')?.value||'').toLowerCase(),state=$('ghostState')?.value||'';const list=all.filter(p=>{if(state==='online'&&!p.online)return false;if(state==='recent'&&p.online)return false;const hay=`${ghostLabel(p)} ${ghostPlace(p)} ${p.device||''} ${p.path||''} ${p.title||''} ${(p.journey||[]).map(x=>`${x.path} ${x.title}`).join(' ')}`.toLowerCase();return!q||hay.includes(q)});body.innerHTML=list.map(p=>{const j=Array.isArray(p.journey)?p.journey:[],last=j[j.length-1]||{},place=ghostPlace(p),route=j.slice(-4).map(x=>x.title||x.path).filter(Boolean).join(' → ')||'1 vista';return`<tr><td>${p.online?'<span class="ghost-online">En línea</span>':'<span class="ghost-offline">Reciente</span>'}</td><td><span class="ghost-badge"><i class="bi bi-incognito"></i> Fantasma</span><div style="margin-top:6px"><b>${esc(ghostLabel(p))}</b><div class="ghost-session-id">${esc(String(p.sessionId||'').slice(-18))}</div></div></td><td>${flag(p.geo?.countryCode)} <b>${esc(place)}</b><div class="muted">IP no almacenada</div></td><td><b>${sessionDeviceGlyph(sessionDeviceLabel(p))} ${esc(sessionDeviceLabel(p))}</b><div class="muted">${sessionDeviceMeta(p)}</div><div class="muted">${geoPill('browser',sessionBrowserLabel(p))}</div></td><td>${date(p.startedAt)}</td><td><b>${formatDuration(p.durationMs)}</b><div class="muted">${Number(p.pageViews||j.length||0)} vistas · ${Number(p.uniquePages||0)} únicas</div></td><td><div class="ghost-path"><b>${esc(last.title||p.title||'Dingloft')}</b><small>${esc(last.path||p.path||'/')}</small></div></td><td><div class="ghost-path"><b>${esc(route)}</b><small>${j.length} paso${j.length===1?'':'s'}</small></div></td><td><button class="btn small ghost-detail" data-id="${esc(p.id)}"><i class="bi bi-chevron-right"></i></button></td></tr>`}).join('')||'<tr><td colspan="9" class="empty">Todavía no hay visitantes fantasma registrados.</td></tr>';document.querySelectorAll('.ghost-detail').forEach(b=>b.onclick=()=>openGhost(presenceSessions.find(p=>p.id===b.dataset.id)))}
function openGhost(p){if(!p)return;activeGhost=p;const j=Array.isArray(p.journey)?p.journey:[];$('ghostModalSub').textContent=`${ghostLabel(p)} · ${ghostPlace(p)}`;$('ghostDetail').innerHTML=`<div class="formgrid"><div class="group"><label>Estado</label><div>${p.online?'<span class="ghost-online">En línea ahora</span>':'Reciente'}</div></div><div class="group"><label>Tiempo activo aproximado</label><div><b>${formatDuration(p.durationMs)}</b></div></div><div class="group"><label>Primera actividad</label><div>${date(p.startedAt)}</div></div><div class="group"><label>Última actividad</label><div>${date(p.lastSeenAt)}</div></div><div class="group"><label>Dispositivo</label><div>${sessionDeviceGlyph(sessionDeviceLabel(p))} ${esc(sessionDeviceLabel(p))} · ${sessionDeviceMeta(p)}<div class="geo-badges" style="margin-top:8px">${geoPill('device',sessionDeviceLabel(p))}${geoPill('browser',sessionBrowserLabel(p))}</div></div></div><div class="group"><label>Ubicación</label><div>${flag(p.geo?.countryCode)} ${esc(ghostPlace(p))}</div></div><div class="group full"><label>Identificador anónimo</label><div class="ghost-session-id">Visitante ${esc(p.visitorId||'—')}<br>Sesión ${esc(p.sessionId||'—')}</div></div></div><div class="ghost-journey">${j.length?j.map((x,i)=>`<div class="ghost-step"><div class="n">${i+1}</div><div><b>${esc(x.title||'Dingloft')}</b><small>${esc(x.path||'/')} · ${date(x.enteredAt)}</small></div><div class="t">${formatDuration(x.activeMs)}</div></div>`).join(''):'<div class="ghost-empty">No hay recorrido disponible todavía.</div>'}</div><div class="ghost-privacy"><i class="bi bi-shield-lock"></i> Este registro usa un identificador aleatorio del navegador y geolocalización aproximada de Cloudflare. No contiene la IP cruda ni ubicación GPS exacta.</div>`;$('ghostModal').classList.add('show')}
