async function uploadMultitrackFile(kind){const input=$(kind==='cover'?'mtCoverFile':'mtPreviewFile');const file=input?.files?.[0];if(!file)throw Error(kind==='cover'?'Selecciona una portada primero.':'Selecciona un audio primero.');const max=kind==='cover'?8*1024*1024:60*1024*1024;if(file.size>max)throw Error(kind==='cover'?'La portada supera 8 MB.':'El preview supera 60 MB.');const u=auth.currentUser;if(!u)throw Error('Sesión no válida');const token=await u.getIdToken();status('mtAdminStatus',kind==='cover'?'Subiendo portada…':'Subiendo audio…','warn');const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),90000);let r;try{r=await fetch(`${WORKER}/admin/multitracks/upload?kind=${encodeURIComponent(kind)}`,{method:'POST',signal:controller.signal,headers:{Authorization:`Bearer ${token}`,'content-type':file.type||'application/octet-stream','x-file-name':encodeURIComponent(file.name)},body:file})}finally{clearTimeout(timer)}const d=await r.json().catch(()=>({}));if(!r.ok||d.ok===false)throw Error(d.error||`Error ${r.status}`);$(kind==='cover'?'mtCover':'mtPreview').value=d.url||'';renderMtMediaPreviews();status('mtAdminStatus',kind==='cover'?'Portada subida.':'Audio subido.','ok')}
